arguments.command:
python -c "
from semver import VersionInfo

# Test R1: Immutability
v = VersionInfo(1, 2, 3)
try:
    v.major = 9
except AttributeError as e:
    print('R1 - major is immutable:', True)

try:
    v.minor = 9
except AttributeError as e:
    print('R1 - minor is immutable:', True)

try:
    v.patch = 9
except AttributeError as e:
    print('R1 - patch is immutable:', True)

try:
    v.prerelease = 'alpha'
except AttributeError as e:
    print('R1 - prerelease is immutable:', True)

try:
    v.build = 'build'
except AttributeError as e:
    print('R1 - build is immutable:', True)

# Test that no new attributes can be set (due to __slots__)
try:
    v.new_attr = 'test'
except AttributeError as e:
    print('R1 - no new attributes allowed:', True)
"
